def transform(grid):
    h,w=len(grid),len(grid[0]); seen=set(); objs=[]
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color and (r,c) not in seen:
                stack=[(r,c)]; seen.add((r,c)); cells=[]
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        q=(y+dy,x+dx)
                        if 0<=q[0]<h and 0<=q[1]<w and q not in seen and grid[q[0]][q[1]]==color:
                            seen.add(q); stack.append(q)
                minr=min(y for y,x in cells); minc=min(x for y,x in cells)
                norm={(y-minr,x-minc) for y,x in cells}
                hh=max(y for y,x in norm)+1; ww=max(x for y,x in norm)+1
                objs.append((minc,color,norm,hh,ww))
    objs.sort()
    out=[[0]*w for _ in range(h)]; top=left=0; prevh=prevw=None
    for i,(_,color,cells,hh,ww) in enumerate(objs):
        if i:
            top += prevh-1; left += prevw-1
        for y,x in cells:
            yy,xx=top+y,left+x
            if 0<=yy<h and 0<=xx<w: out[yy][xx]=color
        prevh,prevw=hh,ww
    return out
